class Solution { fun smallestStringWithSwaps(s:String,pairs:List<List<Int>>):String{val parent=IntArray(s.length){it};fun find(value:Int):Int{var node=value;while(parent[node]!=node){parent[node]=parent[parent[node]];node=parent[node]};return node};for(pair in pairs){val a=find(pair[0]);val b=find(pair[1]);if(a!=b)parent[b]=a};val groups=mutableMapOf<Int,MutableList<Int>>();for(i in s.indices)groups.getOrPut(find(i)){mutableListOf()}.add(i);val answer=s.toCharArray();for(indices in groups.values){val letters=indices.map{s[it]}.sorted();for(i in indices.indices)answer[indices[i]]=letters[i]};return answer.concatToString()} }
